import sys

def main():
    total = 0
    for line in sys.stdin:
        parts = line.split()
        for part in parts:
            try:
                try:
                    num = int(part)
                except ValueError:
                    if not part.lstrip('-').isdigit():
                        raise ValueError("Invalid input")
                    num = int(part)
                total += num
            except ValueError:
                pass
    print(f"Sum of entered integers: {total}")

if __name__ == "__main__":
    main()
